shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-dark: #c9c2b2;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --navy-line: #294057;
    --teal-accent: #1d6b63;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Language Switching Protocol */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: 'Noto Serif SC', 'Lora', Georgia, serif;
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: 'Lora', Georgia, serif;
    line-height: 1.78;
  }

  /* Sticky Masthead */
  .wsj-masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--line-dark);
    padding: 0.7rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .masthead-brand {
    display: flex;
    align-items: baseline;
    gap: 0.85rem;
  }

  .wsj-logo {
    font-family: 'Playfair Display', serif;
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .wsj-desk {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    padding-left: 0.85rem;
    border-left: 1px solid var(--line-dark);
  }

  .lang-switcher {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-radius: 3px;
    overflow: hidden;
  }

  .lang-btn {
    appearance: none;
    border: none;
    background: transparent;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.35rem 0.75rem;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.18s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero-header {
    max-width: 1120px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 3px double var(--line-dark);
  }

  .hero-kicker {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    font-family: 'JetBrains Mono', 'Noto Sans SC', sans-serif;
    font-size: 0.78rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    margin-bottom: 1.1rem;
  }

  .kicker-pill {
    background: var(--accent-soft);
    color: var(--accent);
    padding: 0.2rem 0.55rem;
    border-radius: 2px;
  }

  .hero-title {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-weight: 700;
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.22;
    color: var(--ink);
    letter-spacing: -0.01em;
    margin-bottom: 1.35rem;
    max-width: 960px;
  }

  :host([lang="en"]) .hero-title {
    font-family: 'Playfair Display', Georgia, serif;
    font-weight: 800;
    line-height: 1.12;
  }

  .hero-meta-grid {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 1.5rem;
    align-items: end;
    padding-top: 1.2rem;
    border-top: 1px solid var(--line);
  }

  .byline-block {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.88rem;
    color: var(--muted);
  }

  .byline-author {
    color: var(--ink);
    font-weight: 600;
  }

  .hero-stat-strip {
    display: flex;
    gap: 1.75rem;
    flex-wrap: wrap;
  }

  .mini-stat {
    border-left: 2px solid var(--accent);
    padding-left: 0.75rem;
  }

  .mini-stat-num {
    font-family: 'JetBrains Mono', monospace;
    font-weight: 700;
    font-size: 1.2rem;
    color: var(--ink);
    line-height: 1.1;
  }

  .mini-stat-lbl {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.72rem;
    color: var(--muted);
    margin-top: 0.15rem;
  }

  /* Main Container & Editorial Grid */
  .editorial-container {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 4rem;
  }

  .section-block {
    margin-bottom: 3.5rem;
  }

  .asymmetric-rail {
    display: grid;
    grid-template-columns: minmax(0, 1.85fr) minmax(260px, 1fr);
    gap: 3rem;
    align-items: start;
  }

  .narrative-col {
    max-width: 680px;
  }

  .side-rail {
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
    position: sticky;
    top: 4.5rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.45rem;
  }

  .prose-lead {
    font-size: 1.26rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.65rem;
    line-height: 1.75;
  }

  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 0.12em;
    font-weight: 600;
  }

  /* Chapter Headers */
  .chapter-banner {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin: 3rem 0 1.75rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--line-dark);
  }

  .chapter-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--paper);
    background: var(--ink);
    padding: 0.2rem 0.55rem;
    letter-spacing: 0.06em;
  }

  .chapter-title {
    font-family: 'Noto Sans SC', 'Inter', sans-serif;
    font-size: 0.95rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--ink);
  }

  /* Derived Pull Quotes & Metric Cards */
  .pull-quote {
    background: var(--paper-card);
    border-top: 3px solid var(--ink);
    border-bottom: 1px solid var(--line-dark);
    padding: 1.5rem 1.35rem;
  }

  .pull-quote .quote-text {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1.15rem;
    font-weight: 600;
    line-height: 1.55;
    color: var(--ink);
    margin-bottom: 0.85rem;
  }

  .pull-quote .quote-attrib {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .metric-card {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.5rem 1.4rem;
    border-left: 4px solid var(--accent);
    border-radius: 2px;
  }

  .metric-val {
    font-family: 'JetBrains Mono', monospace;
    font-size: 2.4rem;
    font-weight: 700;
    color: #f3a86c;
    line-height: 1.05;
    margin-bottom: 0.45rem;
  }

  .metric-lbl {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--paper);
    margin-bottom: 0.4rem;
  }

  .metric-note {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    color: #b7c4d1;
    line-height: 1.45;
  }

  /* Bespoke Editorial Dossier Cards */
  .dossier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    padding: 1.35rem;
  }

  .dossier-head {
    font-family: 'JetBrains Mono', 'Noto Sans SC', sans-serif;
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    margin-bottom: 0.85rem;
    padding-bottom: 0.45rem;
    border-bottom: 1px solid var(--line);
  }

  .dossier-item {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 0.75rem;
    padding: 0.5rem 0;
    border-bottom: 1px dashed var(--line-dark);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.84rem;
  }

  .dossier-item:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .dossier-k {
    color: var(--muted);
  }

  .dossier-v {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-weight: 600;
    color: var(--ink);
    text-align: right;
  }

  /* Full-Bleed Visual Diagram Exhibits */
  .exhibit-panel {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 2px solid var(--ink);
    padding: 2rem 1.75rem;
    margin: 2.75rem 0;
  }

  .exhibit-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.35rem;
  }

  .exhibit-kicker {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
  }

  .exhibit-title {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--ink);
    margin-top: 0.25rem;
  }

  .exhibit-sub {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.84rem;
    color: var(--muted);
  }

  .svg-wrap {
    width: 100%;
    overflow: hidden;
    background: var(--paper);
    border: 1px solid var(--line-dark);
    padding: 0.75rem;
  }

  .exhibit-caption-bar {
    margin-top: 1rem;
    padding-top: 0.75rem;
    border-top: 1px solid var(--line-dark);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.84rem;
    color: var(--muted);
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .exhibit-caption-bar .prose-p {
    font-size: 0.86rem;
    color: var(--muted);
    margin-bottom: 0;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
  }

  /* Footer */
  .wsj-footer {
    border-top: 2px solid var(--ink);
    max-width: 1120px;
    margin: 0 auto;
    padding: 2rem 1.5rem 3.5rem;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.8rem;
    color: var(--muted);
  }

  @media (max-width: 860px) {
    .asymmetric-rail {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .side-rail {
      position: static;
    }
    .hero-meta-grid {
      grid-template-columns: 1fr;
    }
    .exhibit-panel {
      padding: 1.35rem 1rem;
    }
  }
